    63	    for scalar in ["é", "中", "😀"] {
    64	        let source = format!("<r>{scalar}</r>");
    65	        for consumed in 1..scalar.len() {
    66	            let mut stepped = XmlTokenStream::new(source.as_bytes(), 16 * size_of::<XmlToken>()).unwrap();
