   124	fn batch_cancelable_apis_cancel_inside_long_lexical_parsing_after_validation() {
   125	    for (prefix, suffix) in [
   126	        (b"<r>".as_slice(), b"</r>".as_slice()),
   127	        (b"<r v='".as_slice(), b"'/>".as_slice()),
   128	        (b"<r><!--".as_slice(), b"--></r>".as_slice()),
   129	        (b"<r><![CDATA[".as_slice(), b"]]></r>".as_slice()),
   130	        (b"<r><?p ".as_slice(), b"?></r>".as_slice()),
   131	        (b"<!DOCTYPE r SYSTEM '".as_slice(), b"'><r/>".as_slice()),
   132	    ] {
   133	        let mut source = prefix.to_vec(); source.extend(std::iter::repeat_n(b'x', 256 * 1024)); source.extend_from_slice(suffix);
   134	        let threshold = source.len() + 2048;
   135	        let mut stream = XmlTokenStream::new(&source, 16 * size_of::<XmlToken>()).unwrap();
   136	        let mut polls = 0;
   137	        let mut cancel = || { polls += 1; polls == threshold };
   138	        loop { let status = stream.step_with_cancel(STEP_CAP, &mut cancel); if status != StreamStatus::Ok { assert_eq!(status, StreamStatus::Canceled); break; } }
   139	        assert!(stream.chars_complete);
   140	        assert_eq!(stream.char_cursor, source.len());
   141	        assert!(stream.bytes_read() > prefix.len());
   142	        assert!(stream.bytes_read() < source.len());
   143	        assert_empty_result(&mut stream, XmlDiagnostic::default());
   144	        for large in [false, true] {
   145	            let mut polls = 0;
   146	            let cancel = || { polls += 1; polls == threshold };
   147	            let (tokens, result, status) = if large { tokenize_large_cancelable(&source, 16, cancel) }
   148	                else { tokenize_cancelable(&source, XmlLimits::default(), 16, cancel) };
   149	            assert_eq!(status, StreamStatus::Canceled);
   150	            assert_eq!(polls, threshold);
   151	            assert!(tokens.is_empty()); assert_eq!(result, XmlResult::default());
   152	        }
   153	    }
   154	}
