  1	/// Byte-at-a-time strict UTF-8 validation. The leading byte's offset remains
  2	/// available for diagnostics while continuation bytes cross step boundaries.
  3	#[derive(Clone, Copy, Default)]
  4	pub(crate) struct Utf8Scan {
  5	    pub(crate) start: usize,
  6	    remaining: u8,
  7	    value: u32,
  8	    minimum: u32,
  9	}
 10	
 11	impl Utf8Scan {
 12	    pub(crate) fn incomplete(&self) -> bool { self.remaining != 0 }
 13	
 14	    pub(crate) fn push(&mut self, byte: u8, offset: usize) -> Result<Option<u32>, usize> {
 15	        if self.remaining == 0 {
 16	            self.start = offset;
 17	            let (remaining, value, minimum) = match byte {
 18	                0x00..=0x7f => return Ok(Some(u32::from(byte))),
 19	                0xc2..=0xdf => (1, u32::from(byte & 0x1f), 0x80),
 20	                0xe0..=0xef => (2, u32::from(byte & 0x0f), 0x800),
 21	                0xf0..=0xf4 => (3, u32::from(byte & 0x07), 0x10000),
 22	                _ => return Err(offset),
 23	            };
 24	            self.remaining = remaining;
 25	            self.value = value;
 26	            self.minimum = minimum;
 27	            return Ok(None);
 28	        }
 29	        if byte & 0xc0 != 0x80 { return Err(self.start); }
 30	        self.value = (self.value << 6) | u32::from(byte & 0x3f);
 31	        self.remaining -= 1;
 32	        if self.remaining != 0 { return Ok(None); }
 33	        if self.value < self.minimum || self.value > 0x10ffff
 34	            || (0xd800..=0xdfff).contains(&self.value)
 35	        {
 36	            return Err(self.start);
 37	        }
 38	        Ok(Some(self.value))
 39	    }
 40	}
