610	static bool stream_scan_characters(xml_scanner *s, size_t budget)
611	{
612	    size_t used = 0U;
613	    while (!cancel_requested(s) && used < budget && s->char_cursor < s->input.len) {
614	        uint8_t byte = byte_at(s, s->char_cursor);
615	        if (s->char_pending_length == 0U) {
616	            s->char_sequence_start = s->char_cursor;
617	            s->char_pending_width = byte < 0x80U ? 1U :
618	                (byte >= 0xc2U && byte <= 0xdfU) ? 2U :
619	                (byte >= 0xe0U && byte <= 0xefU) ? 3U :
620	                (byte >= 0xf0U && byte <= 0xf4U) ? 4U : 1U;
621	        }
622	        s->char_pending[s->char_pending_length++] = byte;
623	        ++s->char_cursor;
624	        ++used;
625	        if (s->char_pending_length == s->char_pending_width) {
626	            size_t next = 0U;
627	            uint32_t cp = 0U;
628	            if (!svg_xml_internal_utf8_next(s->char_pending, s->char_pending_length, &next, &cp) ||
629	                next != s->char_pending_length) {
630	                fail(s, SVG_XML_ERROR_INVALID_UTF8, s->char_sequence_start);
631	                return false;
632	            }
633	            if (!svg_xml_internal_char(cp)) {
634	                fail(s, SVG_XML_ERROR_INVALID_CHARACTER, s->char_sequence_start);
635	                return false;
636	            }
637	            s->char_pending_length = 0U;
638	            s->char_pending_width = 0U;
639	        }
640	    }
641	    if (s->char_cursor == s->input.len) {
642	        if (s->char_pending_length != 0U) {
643	            fail(s, SVG_XML_ERROR_INVALID_UTF8, s->char_sequence_start);
644	            return false;
645	        }
646	        s->chars_complete = true;
647	    }
648	    return !s->canceled && s->result.diagnostic.category == SVG_XML_ERROR_NONE;
717	svg_xml_stream_status svg_xml_token_stream_step(svg_xml_token_stream *stream, size_t byte_budget)
718	{
719	    if (stream == NULL || byte_budget == 0U) return SVG_XML_STREAM_FAILED;
720	    xml_scanner *s = &stream->scanner;
721	    if (s->canceled) return SVG_XML_STREAM_CANCELED;
722	    if (s->result.diagnostic.category != SVG_XML_ERROR_NONE) return SVG_XML_STREAM_FAILED;
723	    if (s->stream_complete) return SVG_XML_STREAM_COMPLETE;
724	    if (byte_budget > 64U * 1024U) byte_budget = 64U * 1024U;
725	    size_t char_initial = s->char_cursor;
726	    if (!stream_scan_characters(s, byte_budget)) {
727	        if (s->canceled) return SVG_XML_STREAM_CANCELED;
728	        s->result.token_count = 0U;
729	        s->result.element_count = 0U;
730	        s->result.attribute_count = 0U;
731	        s->result.node_count = 0U;
732	        return SVG_XML_STREAM_FAILED;
733	    }
734	    if (!s->chars_complete) return SVG_XML_STREAM_OK;
735	    size_t char_work = s->char_cursor - char_initial;
736	    if (char_work >= byte_budget) return SVG_XML_STREAM_OK;
737	    size_t parse_budget = byte_budget - char_work;
738	    size_t initial = stream_frontier(s);
739	    size_t limit = 0U;
740	    if (!add_size(initial, parse_budget, &limit) || limit > s->input.len) limit = s->input.len;
741	    while (!cancel_requested(s) && s->cursor < s->input.len &&
742	           stream_frontier(s) - initial < parse_budget) {
743	        size_t before = stream_frontier(s);
744	        if (!stream_parse_next(s, limit) || stream_frontier(s) == before) break;
745	    }
746	    if (s->canceled) return SVG_XML_STREAM_CANCELED;
747	    if (s->result.diagnostic.category != SVG_XML_ERROR_NONE) {
748	        s->result.token_count = 0U;
749	        s->result.element_count = 0U;
750	        s->result.attribute_count = 0U;
751	        s->result.node_count = 0U;
752	        return SVG_XML_STREAM_FAILED;
753	    }
754	    if (s->chars_complete && s->cursor == s->input.len) {
755	        if (s->depth != 0U || s->root_count == 0U)
756	            fail(s, SVG_XML_ERROR_INCOMPLETE_DOCUMENT, s->input.len);
757	        else s->stream_complete = true;
758	        if (s->result.diagnostic.category != SVG_XML_ERROR_NONE) {
759	            s->result.token_count = 0U;
760	            s->result.element_count = 0U;
761	            s->result.attribute_count = 0U;
762	            s->result.node_count = 0U;
763	            return SVG_XML_STREAM_FAILED;
764	        }
765	    }
766	    return s->stream_complete ? SVG_XML_STREAM_COMPLETE : SVG_XML_STREAM_OK;
532	    s->tag_token_capacity = XML_MAX_ATTRIBUTES_PER_ELEMENT + 1U;
533	    size_t scratch_bytes = 0U;
534	    if (!base_size_mul(s->tag_token_capacity, sizeof(*s->tag_tokens),
535	                       &scratch_bytes)) {
536	        free(stream);
537	        return SVG_XML_STREAM_FAILED;
538	    }
539	    s->tag_tokens = malloc(scratch_bytes);
540	    if (s->tag_tokens == NULL) {
541	        free(stream);
542	        return SVG_XML_STREAM_FAILED;
543	    }
544	    s->input = input;
545	    s->options = svg_xml_default_options();
546	    s->options.limits.input_bytes = 1024U * 1024U * 1024U;
547	    s->result.diagnostic.category = SVG_XML_ERROR_NONE;
548	    s->visitor = visitor;
549	    s->visitor_context = visitor_context;
550	    s->cancel_check = canceled;
551	    s->cancel_context = cancel_context;
552	    if (starts(s, 0U, "\xef\xbb\xbf", 3U)) s->cursor = 3U;
553	    *out_stream = stream;
554	    return SVG_XML_STREAM_OK;
