  4	fn finish(stream: &mut XmlTokenStream<'_>, budget: usize) -> StreamStatus {
  5	    for _ in 0..stream.source.len().saturating_mul(3).saturating_add(64) {
  6	        let scanned = stream.char_cursor;
  7	        let parsed = stream.bytes_read();
  8	        let status = stream.step(budget, false);
  9	        assert!(stream.char_cursor.saturating_sub(scanned)
 10	            + stream.bytes_read().saturating_sub(parsed) <= budget.min(STEP_CAP));
 11	        if status != StreamStatus::Ok { return status; }
 12	    }
 13	    panic!("stream stalled at scan={} parse={}", stream.char_cursor, stream.bytes_read());
 14	}
