 79	            assert_eq!(stream.char_cursor, 3 + consumed);
 80	            assert_eq!(stream.utf8.start, 3);
 81	            assert!(stream.utf8.incomplete());
 82	            assert_empty_result(&mut stream, XmlDiagnostic::default());
